/* Agenda da equipe: datas e horários locais, compartilhados na base online. */
(function(root){'use strict';
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),clone=x=>JSON.parse(JSON.stringify(x)),today=()=>{let d=new Date();return dateKey(d)},dateKey=d=>[d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-');
let api,month=today().slice(0,7),mode='month',person='',busy=false;
function validDate(v){let d=new Date(v+'T12:00:00');return /^\d{4}-\d{2}-\d{2}$/.test(v)&&!isNaN(d)&&dateKey(d)===v}
function validate(s,e){if(!e.id||!e.title?.trim())throw Error('Informe o título do compromisso.');if(!validDate(e.startDate)||!validDate(e.endDate)||e.endDate<e.startDate)throw Error('Confira as datas de início e término.');if(!e.allDay){if(!/^([01]\d|2[0-3]):[0-5]\d$/.test(e.startTime)||!/^([01]\d|2[0-3]):[0-5]\d$/.test(e.endTime)||e.startDate===e.endDate&&e.endTime<=e.startTime)throw Error('O horário final deve ser posterior ao inicial.');}if(e.project&&!s.projects.some(p=>p.id===e.project))throw Error('Obra não encontrada.');if(!Array.isArray(e.participants)||new Set(e.participants).size!==e.participants.length||e.participants.some(id=>!(s.responsibles||[]).some(p=>p.id===id)))throw Error('Confira os participantes.');return true}
function save(s,event,expected){validate(s,event);let n=clone(s),list=n.calendarEvents||[],old=list.find(e=>e.id===event.id);if(expected!==undefined&&JSON.stringify(old||null)!==JSON.stringify(expected))throw Error('Este compromisso foi alterado em outro acesso. Feche e abra novamente.');let e={...clone(event),title:event.title.trim(),updatedAt:new Date().toISOString()};n.calendarEvents=list.filter(x=>x.id!==e.id).concat(e);n.history.unshift({id:'H-calendar-'+Date.now()+'-'+Math.random().toString(36).slice(2),time:e.updatedAt,kind:'calendarEvents',record:e.id,action:old?'Compromisso atualizado':'Compromisso criado',before:old||null,after:e});return n}
function remove(s,id,expected){let n=clone(s),old=(n.calendarEvents||[]).find(e=>e.id===id);if(!old||JSON.stringify(old)!==JSON.stringify(expected))throw Error('Este compromisso mudou. Feche e abra novamente.');n.calendarEvents=n.calendarEvents.filter(e=>e.id!==id);n.history.unshift({id:'H-calendar-remove-'+Date.now(),time:new Date().toISOString(),kind:'calendarEvents',record:id,action:'Compromisso excluído',before:old,after:null});return n}
function events(s,start,end){return(s.calendarEvents||[]).filter(e=>e.startDate<=end&&e.endDate>=start&&(!person||e.participants.includes(person))).sort((a,b)=>a.startDate.localeCompare(b.startDate)||(a.startTime||'').localeCompare(b.startTime||'')||a.title.localeCompare(b.title))}
const button=(a,t,cls='secondary')=>`<button type="button" class="button ${cls}" data-action="shared-calendar:${a}">${t}</button>`;
function label(s,e){return(e.participants||[]).map(id=>(s.responsibles||[]).find(p=>p.id===id)?.name||'Participante removido').join(', ')||'Toda a equipe'}
function card(s,e){return `<button type="button" class="calendar-event ${e.status==='Concluído'?'calendar-complete':''}" data-action="shared-calendar:edit:${esc(e.id)}"><strong>${esc(e.allDay?'Dia inteiro':e.startTime)} · ${esc(e.title)}</strong><small>${esc(label(s,e))}</small>${e.location?`<small>${esc(e.location)}</small>`:''}</button>`}
function render(s){let first=new Date(month+'-01T12:00:00'),start=new Date(first);start.setDate(1-first.getDay());let days=Array.from({length:42},(_,i)=>{let d=new Date(start);d.setDate(start.getDate()+i);return dateKey(d)}),list=events(s,days[0],days[41]);let heading=first.toLocaleDateString('pt-BR',{month:'long',year:'numeric'});return `<div class="page-head"><div><h1>Agenda compartilhada</h1><p>Compromissos de toda a equipe. Todos os usuários do sistema podem consultar e editar.</p></div>${button('new','+ Novo compromisso','primary')}</div><div class="calendar-toolbar">${button('prev','‹ Mês anterior')}${button('today','Hoje')}${button('next','Próximo mês ›')}<h2>${esc(heading)}</h2><label>Visualização <select id="calendarMode"><option value="month" ${mode==='month'?'selected':''}>Mês</option><option value="list" ${mode==='list'?'selected':''}>Lista</option></select></label><label>Participante <select id="calendarPerson"><option value="">Todos</option>${(s.responsibles||[]).map(p=>`<option value="${esc(p.id)}" ${p.id===person?'selected':''}>${esc(p.name)}</option>`).join('')}</select></label></div>${mode==='month'?`<div class="calendar-scroll"><div class="shared-calendar">${['Dom','Seg','Ter','Qua','Qui','Sex','Sáb'].map(d=>`<div class="calendar-weekday">${d}</div>`).join('')}${days.map(day=>`<section class="calendar-day ${day.slice(0,7)!==month?'calendar-other':''} ${day===today()?'calendar-today':''}"><button class="text-btn calendar-date" data-action="shared-calendar:day:${day}" aria-label="Novo compromisso em ${day}">${Number(day.slice(8))}</button>${list.filter(e=>e.startDate<=day&&e.endDate>=day).map(e=>card(s,e)).join('')}</section>`).join('')}</div></div><p class="muted">Toque em um dia para agendar ou em um compromisso para editar. No celular, deslize o calendário para os lados ou use Lista.</p>`:`<div class="calendar-list">${events(s,month+'-01',dateKey(new Date(first.getFullYear(),first.getMonth()+1,0))).map(e=>`<article><div>${esc(new Date(e.startDate+'T12:00:00').toLocaleDateString('pt-BR'))}${e.endDate!==e.startDate?' até '+esc(new Date(e.endDate+'T12:00:00').toLocaleDateString('pt-BR')):''} · ${esc(e.status)}</div>${card(s,e)}</article>`).join('')||'<div class="empty">Nenhum compromisso neste mês.</div>'}</div>`}`}
function bind(){let m=document.querySelector('#calendarMode'),p=document.querySelector('#calendarPerson');if(m)m.onchange=()=>{mode=m.value;api.render()};if(p)p.onchange=()=>{person=p.value;api.render()}}
function open(id,day){let s=api.getState(),old=(s.calendarEvents||[]).find(e=>e.id===id);if(id&&!old)return api.toast('Compromisso não encontrado.');let e=clone(old||{id:'CAL-'+Date.now()+'-'+Math.random().toString(36).slice(2),title:'',startDate:day||today(),endDate:day||today(),startTime:'08:00',endTime:'09:00',allDay:false,participants:[],project:'',location:'',description:'',status:'Agendado'}),dialog=document.querySelector('#reader');document.querySelector('#readerTitle').textContent=old?'Editar compromisso':'Novo compromisso';const input=(name,title,type='text')=>`<label>${title}<input name="${name}" type="${type}" value="${esc(e[name])}" ${['title','startDate','endDate'].includes(name)?'required':''}></label>`;document.querySelector('#readerContent').innerHTML=`<form id="calendarForm"><div class="form-grid">${input('title','Compromisso')}${input('startDate','Data inicial','date')}${input('endDate','Data final','date')}<label><input name="allDay" type="checkbox" ${e.allDay?'checked':''}> Dia inteiro</label>${input('startTime','Hora inicial','time')}${input('endTime','Hora final','time')}${input('location','Local')}<label>Obra (opcional)<select name="project"><option value="">Sem vínculo com obra</option>${s.projects.map(p=>`<option value="${esc(p.id)}" ${e.project===p.id?'selected':''}>${esc(p.name)}</option>`).join('')}</select></label><label>Status<select name="status">${['Agendado','Concluído','Cancelado'].map(v=>`<option ${e.status===v?'selected':''}>${v}</option>`).join('')}</select></label><label>Observações<textarea name="description">${esc(e.description)}</textarea></label></div><fieldset><legend>Participantes (opcional)</legend><p>Sem seleção, o compromisso fica destinado a toda a equipe.</p>${(s.responsibles||[]).map(p=>`<label class="calendar-participant"><input name="participant" type="checkbox" value="${esc(p.id)}" ${e.participants.includes(p.id)?'checked':''}> ${esc(p.name)}</label>`).join('')||'<p>Cadastre pessoas em Gerenciamento de obras → Responsáveis.</p>'}</fieldset><p id="calendarError" role="alert" class="form-error"></p><div class="dialog-actions">${old?'<button type="button" id="calendarDelete" class="button secondary red-text">Excluir compromisso</button>':''}<button type="button" id="calendarCancel" class="button secondary">Cancelar</button><button type="submit" class="button primary">Salvar compromisso</button></div></form>`;dialog.showModal();let form=document.querySelector('#calendarForm'),all=form.elements.allDay;const times=()=>{form.elements.startTime.disabled=all.checked;form.elements.endTime.disabled=all.checked};all.onchange=times;times();form.elements.startDate.onchange=()=>{if(form.elements.endDate.value<form.elements.startDate.value)form.elements.endDate.value=form.elements.startDate.value};document.querySelector('#calendarCancel').onclick=()=>{if(!busy)dialog.close()};async function commit(fn){if(busy)return;busy=true;form.querySelectorAll('button').forEach(b=>b.disabled=true);try{if(await api.save(fn(api.getState()))===false)throw Error('O servidor não confirmou o salvamento.');dialog.close();api.render();api.toast('Agenda atualizada.')}catch(err){document.querySelector('#calendarError').textContent=err.message}finally{busy=false;form.querySelectorAll('button').forEach(b=>b.disabled=false)}}form.onsubmit=ev=>{ev.preventDefault();let next={...e};for(let key of ['title','startDate','endDate','startTime','endTime','location','project','description','status'])next[key]=form.elements[key].value;next.allDay=all.checked;next.participants=[...form.querySelectorAll('[name=participant]:checked')].map(i=>i.value);commit(s=>save(s,next,old||null))};let del=document.querySelector('#calendarDelete');if(del)del.onclick=()=>{if(confirm('Excluir este compromisso da agenda compartilhada?'))commit(s=>remove(s,e.id,old))}}
function handle(action){if(!action?.startsWith('shared-calendar:'))return false;let a=action.slice(16);if(a==='new')open();else if(a.startsWith('edit:'))open(a.slice(5));else if(a.startsWith('day:'))open(null,a.slice(4));else{if(a==='today')month=today().slice(0,7);else{let d=new Date(month+'-01T12:00:00');d.setMonth(d.getMonth()+(a==='prev'?-1:1));month=dateKey(d).slice(0,7)}api.render()}return true}
root.EngefexSharedCalendar={init:a=>api=a,render,bind,handle,validate,save,remove,events,busy:()=>busy};
})(typeof window==='undefined'?globalThis:window);
